/// MPJ_22159 Collections note DCP 12/04/2022
/// </summary>
[ExtensionOf(tableStr(CustTable))]
final class METCustTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Find logo to use on customer-facing reports for specified customer.
    /// MPJ_13531_CustReportLogos
    /// </summary>
    /// <param name = "_custAccount">Customer account</param>
    /// <returns>Bitmap to use, or null if no specific image specified. (ie use default)</returns>
    static Image metGetCustReportLogo(CustAccount _custAccount)
    {
        METCustTable    metCustTable = METCustTable::find(_custAccount);
        Image           img;
        CompanyInfo     companyInfo;
        CompanyImage    companyImage;
        METCompanyImage metCompanyImage;

        if(metCustTable && metCustTable.IndustryKey)
        {
            companyInfo = CompanyInfo::find();

            switch(METIndustryKeyTable::find(metCustTable.IndustryKey).Logo)
            {
                case METIndustryKeyLogo::Logo1:
                    img = CompanyImage::metGetImage(companyInfo);
                    break;

                case METIndustryKeyLogo::Logo2:
                    img = METCompanyImage::getImage(companyInfo, METCompanyImageType::CompanyLogo);
                    break;
                
                case METIndustryKeyLogo::Logo3:
                    img = METCompanyImage::getImage(companyInfo, METCompanyImageType::CompanyLogo3);
                    break;
                
                case METIndustryKeyLogo::Logo4:
                    img = METCompanyImage::getImage(companyInfo, METCompanyImageType::CompanyLogo4);
                    break;
            }                
            
        }
        return img;
    }

    /// <summary>
    /// MPJ_4050_CustomerPaymentsOpen
    /// </summary>
    /// <param name = "_CustTable">
    /// get the table buffer
    /// </param>
    /// <returns>
    /// return MainContactWorker worker 
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    static display Name getMETMainContactWorker(CustTable   _CustTable)
    {
        HcmWorker       metHcmWorker;
        DirPersonName   metDirPersonName;
        DirPartyTable   metDirPartyTable;

        select firstonly TableId from _CustTable
            join TableId from metHcmWorker
                where metHcmWorker.RecId == _CustTable.MainContactWorker
            join TableId from metDirPersonName
                where metDirPersonName.Person == metHcmWorker.Person
            join TableId from metDirPartyTable
                where metDirPartyTable.RecId == metDirPersonName.Person;

        return metDirPartyTable.Name;

    }

    /// <summary>
    /// Validate field value.
    /// </summary>
    /// <param name = "p1">
    /// Field Id
    /// </param>
    /// <returns>true if validation succeeds; else false.</returns>
    boolean validateField(FieldId p1)
    {
        boolean ret;

        ret = next validateField(p1);

        switch (p1)
        {
            case fieldNum(CustTable, CredManAccountStatusId) :
                ret = this.metAllowAccountStatusUpdate();

        }

        return ret;
    }

    /// <summary>
    /// Account status cannot be updated to Closed if balance exists.
    /// </summary>
    /// <returns>true if ZERO balance; else false.</returns>
    public boolean metAllowAccountStatusUpdate()
    {
        boolean ret = true;

        if (this.CredManAccountStatusId == METConstants::custAccountStatusClosed
            && this.balanceAllCurrency() != 0)
        {
            ret = checkFailed("@MET:AccountClosingCheck");
        }

        return ret;
    }

    /// <summary>
    /// MPJ_3735_Aged Balance
    /// </summary>
    /// <param name = "_CustTable">
    /// get CustTable record
    /// </param>
    /// <returns>
    /// return ChainId Description
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    static display Description getMETCompanyChainName(CustTable   _CustTable)
    {
        smmBusRelChainGroup     metsmmBusRelChainGroup;
        
        select firstonly Description
            from    metsmmBusRelChainGroup
            where   metsmmBusRelChainGroup.ChainId == _CustTable.CompanyChainId;

        return metsmmBusRelChainGroup.Description;

    }

    /// <summary>
    /// MPJ_3735_Aged Balance 
    /// </summary>
    /// <param name = "_CustTable">
    ///  get CustTable record
    /// </param>
    /// <returns>
    /// return customer group name 
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    static display Description getMETCustomerGroupName(CustTable   _custTable)
    {
        CustGroup   metCustGroup;

        select firstOnly Name
            from    metCustGroup
            where   metCustGroup.CustGroup == _CustTable.CustGroup;

        return metCustGroup.Name;
    }

    /// <summary>
    /// MPJ_3735_Aged Balance
    /// </summary>
    /// <param name = "_custTable">
    /// get CustTable record
    /// </param>
    /// <returns>
    /// return outstanding credit limit percent 
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    static display Percent getMETCreditLimitOutstanding(CustTable _custTable)
    {
        percent                     metCreditLimitOutstanding;
        CustAging                   metCustaging;
        CustAgingLegalEntityView    metCustAgingLegalEntityView;
        
        select firstonly SumOfAmountDueMst, SumOfCreditLimitMst 
            from    metCustAgingLegalEntityView
            exists join metCustaging
            where   metCustaging.RecId      == metCustAgingLegalEntityView.CustAging
            &&      metCustaging.CustTable  == _custTable.AccountNum;

        if(metCustAgingLegalEntityView.SumOfCreditLimitMst == 0)
        {
            metCreditLimitOutstanding = 0;
        }
        
        if(metCustAgingLegalEntityView.SumOfCreditLimitMst != 0)
        {
            metCreditLimitOutstanding = ((metCustAgingLegalEntityView.SumOfAmountDueMst / metCustAgingLegalEntityView.SumOfCreditLimitMst) *100);
        }
        
        return metCreditLimitOutstanding;
    }

    /// <summary>
    /// MPJ_1663_Amex balance to be added to Aged Balance Inquiry
    /// </summary>
    /// <param name = "_custTable">
    /// get cust table record
    /// </param>
    /// <returns>
    /// return AMEXBalance
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    static display METAMEXBalance getMETamexbalance(CustTable _custTable)
    {
        METCustTable    metCustTable;

        select firstonly AccountNum, AMEXBalance from metCustTable
            where  metCustTable.AccountNum  == _custTable.AccountNum;

        return metCustTable.AMEXBalance;
    }

    /// <summary>
    /// Display Remaing amount
    /// </summary>
    /// <param name = "_custTable">get cust table record</param>
    /// <returns>Remaining Amount</returns>
    static display AmountMST getRemainAmountMST(CustTable _custTable)
    {
        CustTrans custTrans;
        AmountMST remainAmountMST;

        while select AmountMST, ExchAdjustment, SettleAmountMST from custTrans
            where CustTrans.accountNum == _custTable.accountNum
            &&    CustTrans.TransType  == LedgerTransType::Payment
        {
            remainAmountMST = custTrans.AmountMST + custTrans.ExchAdjustment - custTrans.SettleAmountMST + remainAmountMST;
        }

        return remainAmountMST;
    }

